/* KONA service worker — generated by tools/build_app.mjs, do not edit sw.js by hand.
 *
 * Updates are atomic and integrity-checked:
 *  - every release ships app/app-manifest.json: a version plus the SHA-256 of every file the app uses;
 *  - a new worker installs only if every core file it downloads hashes to the manifest's value
 *    (a stale CDN copy, a truncated download or a tampered file fails the install, and the
 *    visitor keeps the last good version);
 *  - heavy files (bikes, paintings, studios) are cached on first use and checked the same way;
 *  - the page is told when a verified update is waiting and applies it only when the visitor taps
 *    "Reload" — never mid-walk.
 * Service workers only run over HTTPS, from this origin, so nothing is fetched from elsewhere.
 */
const VERSION = '__VERSION__';
const MANIFEST = __MANIFEST__;
const CORE = `speedmax-core-${VERSION}`;
const ASSETS = 'speedmax-assets';                                    // shared across versions; entries carry their hash
const scopeUrl = p => new URL(p, self.registration.scope).href;
const OFFLINE = '<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline · KONA</title>'
  + '<body style="margin:0;display:grid;place-items:center;min-height:100vh;background:#f4efe7;color:#12181d;font:15px/1.6 system-ui,sans-serif;text-align:center;padding:24px">'
  + '<div><p style="letter-spacing:.24em;font-size:11px;text-transform:uppercase;font-weight:700">KONA</p>'
  + '<h1 style="font:400 38px Georgia,serif;margin:8px 0">KONA can\'t be reached</h1>'
  + '<p>You are offline. Reconnect and try again.</p></div>';

async function sha256(buf) {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
  let s = ''; for (const b of d) s += String.fromCharCode(b);
  return btoa(s);
}
async function fetchVerified(path, expected) {
  const res = await fetch(scopeUrl(path), { cache: 'reload', credentials: 'omit', redirect: 'error' });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  const buf = await res.arrayBuffer();
  const got = await sha256(buf);
  if (got !== expected) throw new Error(`${path}: integrity mismatch`);
  const headers = new Headers(res.headers); headers.set('x-sha256', got);
  return new Response(buf, { status: 200, headers });
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CORE);
    const verified = await Promise.all(MANIFEST.core.map(async p => [p, await fetchVerified(p, MANIFEST.files[p])]));
    for (const [p, res] of verified) await cache.put(scopeUrl(p), res);   // only after every file checked out
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('speedmax-core-') && k !== CORE) await caches.delete(k);
    const assets = await caches.open(ASSETS);                          // drop assets this release no longer lists
    for (const req of await assets.keys()) { const p = new URL(req.url).pathname.replace(new URL(self.registration.scope).pathname, ''); if (!MANIFEST.files[p]) await assets.delete(req); }
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data === 'skip-waiting') self.skipWaiting();
  if (event.data === 'version') event.source?.postMessage({ type: 'version', version: VERSION });
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;   // fonts, Wikimedia: straight to the network
  let path = url.pathname.slice(new URL(self.registration.scope).pathname.length);
  if (req.mode === 'navigate' && (path === '' || path.endsWith('/'))) path += 'index.html';
  const expected = MANIFEST.files[path];
  if (!expected) return;
  event.respondWith((async () => {
    const core = await caches.open(CORE);
    const hit = await core.match(scopeUrl(path));
    if (hit) return hit;
    const assets = await caches.open(ASSETS);
    const a = await assets.match(scopeUrl(path));
    if (a && a.headers.get('x-sha256') === expected) return a;
    try {
      const res = await fetchVerified(path, expected);
      await assets.put(scopeUrl(path), res.clone());
      return res;
    } catch (e) {
      // A deployment can race this worker, so a newer network copy may legitimately fail this
      // release's hash. It may be displayed, but never cached under the old hash.
      try {
        const live = await fetch(req);
        if (live) return live;
      } catch (_) {}
      // Never reject respondWith or resolve undefined. Navigations get an honest offline page;
      // signed assets get a concrete 504 response.
      if (req.mode === 'navigate') return new Response(OFFLINE, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
      return new Response('', { status: 504, statusText: 'Offline' });
    }
  })());
});
